import raytracerVertex from "./shaders/raytracer-vert.glsl";
import raytracerFragment from "./shaders/raytracer-frag.glsl";
import { WebGLUtils } from "../lib/webgl-utils";
import { Shader } from "./lib/Shader";
import { MatMath } from "./lib/Math/Matrix";
import { CameraPerspective } from "./lib/CameraPerspective";
// add listener to call main function
window.addEventListener("DOMContentLoaded", main);
class RayTracerApp {
    constructor() {
        // app state
        this.awaitingDraw = false;
        // initialize webgl
        let canvas = document.getElementById('webgl');
        global.gl = WebGLUtils.setupWebGL(canvas);
        if (gl == null) {
            throw new Error("Failed to initialize WebGL");
        }
        this.camera = new CameraPerspective({
            aspectRatio: canvas.width / canvas.height,
            fov: 40
        });
        // initialize opengl drawing
        this.canvasMesh = gl.createBuffer();
        this.createSquare(this.canvasMesh);
        this.shader = new Shader(raytracerVertex, raytracerFragment);
        this.shader.bindMeshAttribs();
        // set blending mode for layered drawing
        gl.blendFunc(gl.ONE, gl.ONE);
        gl.enable(gl.BLEND);
        gl.clearColor(0, 0, 0, 1);
        this.requestFrame();
    }
    createSquare(buffer) {
        gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
        gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([
            -1, -1,
            1, -1,
            1, 1,
            -1, 1
        ]), gl.STATIC_DRAW);
    }
    requestFrame() {
        if (!this.awaitingDraw) {
            this.awaitingDraw = true;
            window.requestAnimFrame(this.render.bind(this));
        }
    }
    render() {
        gl.clear(gl.COLOR_BUFFER_BIT);
        // create a matrix to transform from clipping space to world space
        const rayMatrix = MatMath.MultiplyM(this.camera.InverseViewMatrix, MatMath.Inverse4(this.camera.ProjectionMatrix));
        this.shader.setUniformMat4f("u_RayMat", rayMatrix);
        gl.drawArrays(gl.TRIANGLE_FAN, 0, 4);
        this.awaitingDraw = false;
    }
    setSceneIndex(index) {
        this.shader.setUniform1i("u_SceneIndex", index);
        this.requestFrame();
    }
}
function main() {
    global.app = new RayTracerApp();
}
