import { Camera } from "./Camera";
import { MatMath } from "./Math/Matrix";
// Default parameters for a perspective camera
const defaultCameraPerspectiveOptions = {
    fov: 90,
    aspectRatio: 16 / 9,
    near: 0.03,
    far: 500
};
// A class representing a perspective camera
export class CameraPerspective extends Camera {
    // Initialize a perspective camera
    constructor(options) {
        let conf = defaultCameraPerspectiveOptions;
        Object.assign(conf, options);
        super(conf);
        this.fov = conf.fov;
    }
    // Get the projection matrix of the camera
    get ProjectionMatrix() {
        return MatMath.Frustum(this.fov, this.aspectRatio, this.near, this.far);
    }
}
